"""Jabberwock boss (your sprite set). All frames face left.
fly: the full wing-beat loop (used for every attack too, so its wings keep flapping while it attacks).
death: knees buckle and it collapses.  Attack effects (the green burble and the spit burst) were lifted from your
attack animations and are drawn at its mouth on top of the flapping frames."""
import base64
import zlib
import pygame

JW, JH = 86, 82
JAX, JAY = 43, 42                     # body centre inside a frame
JAB = {'fly': (17, ''),
       'death': (17, '')}
MOUTH = [(-35, -21), (-36, -22), (-37, -23), (-39, -24), (-41, -24), (-42, -24), (-43, -23), (-43, -23), (-42, -20), (-41, -21), (-39, -21), (-37, -20), (-36, -20), (-36, -19), (-36, -18), (-36, -18), (-36, -19)]                           # mouth offset from the body centre for each flight frame (1x)
DEATH_BOTTOM = [36, 36, 36, 36, 36, 36, 37, 37, 38, 38, 38, 38, 38, 39, 38, 38, 38]                    # lowest pixel below the body centre in each death frame (1x)
FX = {'beam': [((34, 21), (-21, -2), 'eNpjYKAt+Pzz439qqKGHO+gBBos7RiqQ/8f6H4RF9zGAMYg9EPajY1i6oEX6gNmBzAbZgwsj66OWX7HlA2LdQS27YWx8dsIwsv6sDSH/qeUGYuzG5gZy7EYPb3LtpmYeGSj7KfH7YPA/tcspWqY9ariDXvZjcwctw53c+mGg6snBUF8PhnYDAHsXHuE='), ((22, 18), (-21, -1), 'eNpjYKAu+Pzz438QZhgi5pIDFP+x/QdhEFt0HwPcXZS4D2YmstkUu/MTD9gskLvm3Jz1H0MOisl1KyxOsGGY3aSaeeTPDLzmwsymplvBZqKFO6GwwWYuehzCMZI5+OSJNhOL23DajYRxmUtMvsPlHmS5Gx9OEJ1+CcUHVjvR/Iwtv6G7DVd6AomTkteIDVtS8y8x8QbLS+TkVWqXNQCa3eby'), ((22, 22), (-21, -1), 'eNpjYKAu+Pzz438QZqCzuQr/WP+DMDXNhZlJyGyYfmL9jW4uuW7HZibMP4TMJtZedHMJmY8sVvOv4D+p5mIz2/Kj2n9k9bjMRdaDzVxc5sPU4woLXGaC3IXPbGQ+sW7F5i58fiA3vgipI8ZcbGqxmU0onRBjLr58k7Uh5D8p4UpMegfFLXoeJyW8SC1/qG0uobxFaTlz5M8MqpmJKz1Qw1xs5qPHLTXNp9QcAPPfZd0='), ((21, 19), (-21, -1), 'eNpjYKAe+Pzz438QZhjkZpIC5P6y/IdhZDch0+Sah24uOUDroTTcHJB7sJlPqj3IemDhj45h8iD7STETl3nImNpmgtQo/GP9jxxm+My78eEEVr/iC1NC4rjCD18c4bMXl3nE5id0N+CLY1LMJBQP2NIMtnxEqpnk5D1amInNbHLyOb64p1bZQal5AJ2ICo8='), ((22, 23), (-21, -1), 'eNpjYKAu+Pzz438QJkWPwj/W/yBMTXNhZpJqLiE9MHm7rRr/YXyYfnzuI+QedDlC7kY3k1j/wtSofRIGY7m/LP9xqYGFDbFuB5mHTCOr13oo/R/dXEJmY1MP04MtDLCpw2Y2Mf7DZSYuPfjMxGcujF/zrwCnXnRxWNoj1k+4xNHFsjaEYDUXl7+JCXtQWsCVZtDV4krb2MzFld9A9uEzF5fZhPIOLjcQkyeJKX9Izb+kmkvt8p0W5hLrN3LNpWY9Rwu3ElsXkgMAhd1O/A=='), ((21, 20), (-21, -1), 'eNpjYMAP5P6y/EfG+NR+/vnxPwiTYh6lZqKbQYyZDET6GZ+bkGlaA2r4CV88UMsuXPGKz0xC6YBUM4lJW6SmF2LVkBpWhOygRTqmdjoCAa2H0hSZSUw+omUeoLZ9tM5b1A4XUstkSssDfAAAE9PEbA==')],
      'spit': [((10, 14), (-4, -3), 'eNpjYMAPPv/8+B+EGUhUB+Pj04usBpdabGqwqR3s6oj1LynqsKllIAJ8a/6KV92nc39xygMABh/ylg=='), ((24, 29), (-13, -10), ''), ((31, 21), (-21, -6), 'eNpjYMAPPp37+5+ByuDzz4//QZiQGgYaAXxmE2Mvshpc6mHiX+V//gdhbP5Hx9+av/4nJtyICT+Y3YTMIGQWKWqJjXdyMTXS3EDYTw27yXUXve2jpd2DMcxJyd/U8ju2fE0LuwdbHvvz8h9Y/smyy/+HY/4e6LKFnnZjM+vnqt8Uly3E6qFFXUJI3/+w/1S1m5J2CzkAAHzFqdA='), ((33, 22), (-21, -6), 'eNpjYBg48Pnnx/8gzDAI3PDn5T+6uONb81eK7KGWOz+d+/sfl/t+rvoNxiA1sPBBxvSKE1yYnumCWAyKF1B4gcKN3m6gZdolxv7BEhe0zJ+kpgdahMtA2UtpOJDjrj3nd/ynlhv+h/3/P9DhQGm5T4obQP79Z/EPA4PcACqjdmx+TdMyaqDq8IF0B8g+9PAGxQMovOnVthgFiLigZhonBwAAnHCLUQ==')]}
SCALE = 2.4
_C = {}


def jab_frame(name, i, scale=SCALE, tint=None):
  n, data = JAB[name]
  i = max(0, min(n - 1, int(i))) if name == 'death' else int(i) % n
  k = (name, i, scale, tint)
  hit = _C.get(k)
  if hit is None:
    if tint:
      s0, ax, ay = jab_frame(name, i, scale)
      s = s0.copy()
      s.fill((110, 110, 130) if tint == 'white' else (150, 0, 0), special_flags=pygame.BLEND_RGB_ADD)
      hit = _C[k] = (s, ax, ay)
      return hit
    raw = _C.get((name, 'raw'))
    if raw is None:
      raw = _C[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    m = JW * JH * 4
    s = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (JW, JH), 'RGBA').copy()
    if scale != 1:
      s = pygame.transform.scale(s, (int(JW * scale), int(JH * scale)))
    hit = _C[k] = (s, int(JAX * scale), int(JAY * scale))
  return hit


def jab_fx(kind, i, scale=SCALE):
  """(surface, dx, dy): an attack effect frame and where it sits relative to the mouth"""
  lst = FX[kind]
  i = int(i) % len(lst)
  k = ('fx', kind, i, scale)
  hit = _C.get(k)
  if hit is None:
    (w, h), (dx, dy), data = lst[i]
    s = pygame.image.frombuffer(zlib.decompress(base64.b64decode(data)), (w, h), 'RGBA').copy()
    s = pygame.transform.scale(s, (int(w * scale), int(h * scale)))
    hit = _C[k] = (s, int(dx * scale), int(dy * scale))
  return hit


def jab_mouth(b, scale=SCALE):
  mx, my = MOUTH[int(b.get('fi', 0)) % 17]
  return b['x'] + 65 + mx * scale, b['y'] + 65 + my * scale


def jab_frames():
  return [jab_frame('fly', i, 2)[0] for i in range(17)]
